<?php

namespace App\Exports;

use App\Enums\ReportType;
use App\Models\Category;
use App\Models\Item;
use App\Models\User;
use App\Reports\ReportFilters;
use App\Reports\ReportResult;
use Illuminate\Support\Collection;

/**
 * Turns a report (ReportResult, with ids and codes) into a ReportDocument (names and labels),
 * the same way the Reports page shows it. BACKEND_HANDOFF.md 4.8, "Export": every file starts with
 * the report information (report, generated by, generated at, period, every filter in words, rows),
 * then the table and the totals.
 */
class ReportDocumentBuilder
{
    /** The names on the Reports page tabs (REPORT_TABS in src/pages/admin/reportConfig.js). */
    public const TITLES = [
        'summary' => 'Inventory Summary',
        'movement_history' => 'Movement History',
        'critical_items' => 'Critical Items',
        'inventory_value' => 'Inventory Value',
    ];

    private const STATUS_LABELS = [
        'available' => 'Available',
        'low_stock' => 'Low Stock',
        'out_of_stock' => 'Out of Stock',
        'expiring_soon' => 'Expiring Soon',
        'expired' => 'Expired',
    ];

    /** Every item, archived ones included (history keeps their transactions): id => item. */
    private Collection $items;

    /** id => name */
    private Collection $categories;

    public function build(ReportResult $report, ReportFilters $filters, User $user): ReportDocument
    {
        $this->items = Item::query()->get(['id', 'name', 'unit'])->keyBy('id');
        $this->categories = Category::query()->pluck('name', 'id');

        [$headings, $money, $row] = $this->table($report->type);
        [$totals, $moneyTotals] = $this->totals($report);

        return new ReportDocument(
            title: 'MediTrack - '.self::TITLES[$report->type->value],
            info: $this->info($report, $filters, $user),
            headings: $headings,
            rows: array_map($row, $report->rows),
            totals: $totals,
            money: $money,
            moneyTotals: $moneyTotals,
        );
    }

    /** The report information block, in the order it is printed. */
    private function info(ReportResult $report, ReportFilters $filters, User $user): array
    {
        $info = [
            'Report' => self::TITLES[$report->type->value],
            'Generated by' => "{$user->name} (".ucfirst($user->role->value).')',
            'Generated at' => now()->format('Y-m-d H:i').' ('.config('app.timezone').')',
            'Period' => $this->period($report->type, $filters),
            'Category' => $filters->categoryId === null ? 'All categories' : $this->categoryName($filters->categoryId),
            'Item' => $filters->itemId === null ? 'All items' : $this->itemName($filters->itemId),
        ];
        if ($filters->search !== null) {
            $info['Search'] = $filters->search;
        }
        $info['Rows'] = (string) $report->rowCount();

        return $info;
    }

    /** "As of today" for the reports that ignore the period (ReportType::usesPeriod). */
    private function period(ReportType $type, ReportFilters $filters): string
    {
        if (! $type->usesPeriod()) {
            return 'As of today';
        }

        return match (true) {
            $filters->from !== null && $filters->to !== null => "{$filters->from->toDateString()} to {$filters->to->toDateString()}",
            $filters->from !== null => "From {$filters->from->toDateString()}",
            $filters->to !== null => "Up to {$filters->to->toDateString()}",
            default => 'All dates',
        };
    }

    /**
     * Per report: the headings, the indexes of the money columns, and how one row becomes cells.
     * The fields of each row are listed in BACKEND_HANDOFF.md 4.8.
     *
     * @return array{0: list<string>, 1: list<int>, 2: callable(array): list<mixed>}
     */
    private function table(ReportType $type): array
    {
        return match ($type) {
            ReportType::Summary => [
                ['Item', 'Category', 'Available Quantity', 'Expired Quantity', 'Unit', 'Status', 'Total Value'],
                [6],
                fn (array $row) => [
                    $this->itemName($row['itemId']), $this->categoryName($row['categoryId']),
                    $row['quantity'], $row['expiredQuantity'], $row['unit'],
                    $this->status($row['status']), $this->money($row['totalValue']),
                ],
            ],
            ReportType::MovementHistory => [
                ['Date', 'Item', 'Type', 'Quantity', 'Unit', 'Supplier', 'Recipient', 'Unit Cost', 'Total Value'],
                [7, 8],
                fn (array $row) => [
                    $row['date'], $this->itemName($row['itemId']), $this->movementType($row),
                    $row['quantity'], $this->items->get($row['itemId'])?->unit?->value,
                    $row['supplier'] ?? null, $row['recipient'] ?? null,
                    $this->money($row['unitCost']), $this->money($row['totalValue']),
                ],
            ],
            ReportType::CriticalItems => [
                ['Item', 'Category', 'Status', 'Quantity', 'Min Qty', 'Unit'],
                [],
                fn (array $row) => [
                    $this->itemName($row['itemId']), $this->categoryName($row['categoryId']),
                    $this->status($row['status']), $row['quantity'],
                    // A minimum means nothing on an expiry row.
                    in_array($row['status'], ['expired', 'expiring_soon'], true) ? null : $row['minQty'],
                    $row['unit'],
                ],
            ],
            ReportType::InventoryValue => [
                ['Item', 'Category', 'Available Quantity', 'Expired Quantity', 'Unit', 'Unit Cost', 'Total Value'],
                [5, 6],
                fn (array $row) => [
                    $this->itemName($row['itemId']), $this->categoryName($row['categoryId']),
                    $row['quantity'], $row['expiredQuantity'], $row['unit'],
                    $this->money($row['unitCost']), $this->money($row['totalValue']),
                ],
            ],
        };
    }

    /**
     * The totals with the labels of the Reports page (the "kpis" in reportConfig.js), and which of
     * them are money.
     *
     * @return array{0: array<string, int|float>, 1: list<string>}
     */
    private function totals(ReportResult $report): array
    {
        $labels = match ($report->type) {
            ReportType::Summary => [
                'totalItems' => 'Total Items', 'available' => 'Available', 'lowStock' => 'Low Stock', 'outOfStock' => 'Out of Stock',
            ],
            ReportType::MovementHistory => [
                'itemsCount' => 'Total Items', 'transactionsCount' => 'Total Transactions', 'incomingCount' => 'Incoming Transactions',
                'outgoingCount' => 'Outgoing Transactions', 'disposalCount' => 'Expired Disposals',
            ],
            ReportType::CriticalItems => [
                'totalItems' => 'Total Items', 'lowStock' => 'Low Stock', 'outOfStock' => 'Out of Stock',
                'expired' => 'Expired', 'expiringSoon' => 'Expiring Soon', 'alerts' => 'Alerts',
            ],
            ReportType::InventoryValue => [
                'totalItems' => 'Total Items', 'stockValue' => 'Available Stock Value', 'incomingValue' => 'Incoming Value',
                'outgoingValue' => 'Outgoing Value', 'expiredValue' => 'Expired Stock Value (awaiting disposal)', 'disposedValue' => 'Disposed Value',
            ],
        };
        $moneyKeys = ['stockValue', 'incomingValue', 'outgoingValue', 'expiredValue', 'disposedValue'];

        $totals = [];
        $moneyTotals = [];
        foreach ($labels as $key => $label) {
            $isMoney = in_array($key, $moneyKeys, true);
            $totals[$label] = $isMoney ? $this->money($report->totals[$key] ?? 0) : (int) ($report->totals[$key] ?? 0);
            if ($isMoney) {
                $moneyTotals[] = $label;
            }
        }

        return [$totals, $moneyTotals];
    }

    private function movementType(array $row): string
    {
        return match (true) {
            $row['type'] === 'incoming' => 'Incoming',
            ($row['reason'] ?? null) === 'expired_disposal' => 'Expired Disposal',
            default => 'Outgoing',
        };
    }

    /** Money to 2 decimals, as a number; null stays empty (a made-up 0 would read as a real total). */
    private function money(int|float|null $value): ?float
    {
        return $value === null ? null : round((float) $value, 2);
    }

    private function status(string $status): string
    {
        return self::STATUS_LABELS[$status] ?? $status;
    }

    private function itemName(int $id): string
    {
        return $this->items->get($id)?->name ?? "Item #{$id}";
    }

    private function categoryName(int $id): string
    {
        return $this->categories->get($id) ?? "Category #{$id}";
    }
}
